"""Silence event composition handler."""

from __future__ import annotations

import asyncio
import time
from typing import Callable, ClassVar, Optional, Sequence

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.channels.voice_stream.call_state import call_state
from rasa.core.voice.event_composition.events import (
    CompositeEvent,
    SilenceTimeoutInteractionEvent,
)
from rasa.core.voice.event_composition.events.input_events import (
    BotPlaybackStartedInputEvent,
    BotPlaybackStoppedInputEvent,
    DTMFKeypressInputEvent,
    FinalTranscriptInputEvent,
    InputEvent,
    PartialTranscriptInputEvent,
    PlaybackMarkerAcknowledgedInputEvent,
    PlaybackMarkerSentInputEvent,
    SessionEndedInputEvent,
)
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()

SilenceDetectedHook = Callable[[], None]


class SilenceHandler:
    """Owns silence monitoring.

    Arms when bot audio drains or a turn ends with nothing playing, and restarts on
    each partial transcript and DTMF keypress; disarms on final transcript, session
    end, and when a turn starts.
    """

    # Subscribe to native and marker playback events so silence monitoring
    # starts when bot audio ends on every channel.
    interested_in: ClassVar[RawEventTypes] = [
        PartialTranscriptInputEvent,
        FinalTranscriptInputEvent,
        SessionEndedInputEvent,
        DTMFKeypressInputEvent,
        PlaybackMarkerSentInputEvent,
        PlaybackMarkerAcknowledgedInputEvent,
        BotPlaybackStartedInputEvent,
        BotPlaybackStoppedInputEvent,
    ]

    def __init__(
        self,
        interaction_event_queue: ConversationQueue[CompositeEvent],
        on_silence_detected: Sequence[SilenceDetectedHook] = (),
    ) -> None:
        """Create a silence handler."""
        self._interaction_event_queue = interaction_event_queue
        self._watcher: Optional[asyncio.Task[None]] = None
        self._on_silence_detected = on_silence_detected
        self._session_ended = False

    async def handle(self, event: InputEvent) -> None:
        """Handle silence-related raw input events."""
        if isinstance(event, SessionEndedInputEvent):
            self._session_ended = True
            self._disarm()
            return

        if isinstance(event, FinalTranscriptInputEvent):
            self._disarm()
            return

        if isinstance(event, (PartialTranscriptInputEvent, DTMFKeypressInputEvent)):
            # A partial transcript or DTMF entry may produce no turn, so restart the
            # countdown here.
            self._disarm()
            self.arm_if_idle()
            return

        if isinstance(
            event,
            (
                PlaybackMarkerSentInputEvent,
                PlaybackMarkerAcknowledgedInputEvent,
                BotPlaybackStartedInputEvent,
                BotPlaybackStoppedInputEvent,
            ),
        ):
            if call_state.is_idle_for_silence():
                self._arm()
            else:
                # New bot audio (pending or playing) must cancel a silence watcher
                # left over from the previous drain edge.
                self._disarm()
            return

        raise TypeError(f"Unexpected event type: {type(event).__name__}")

    def arm_if_idle(self) -> None:
        """Start or restart the silence timeout watcher if the call is idle.

        Covers a turn that ends with nothing left to play: it sent no audio
        (e.g. Mantle ``listen``), or its audio finished while Rasa was still
        processing. While bot audio still plays, this does nothing, and the
        playback-stopped event arms the watcher instead. After the session has
        ended it never arms, so no watcher outlives the call.
        """
        if not self._session_ended and call_state.is_idle_for_silence():
            self._arm()

    def disarm(self) -> None:
        """Cancel any in-flight silence timeout watcher."""
        self._disarm()

    def _arm(self) -> None:
        """Start or restart the silence timeout watcher."""
        timeout = call_state.silence_timeout
        if not timeout:
            return

        self._disarm()
        structlogger.debug(
            "silence_handler.arm",
            timeout=timeout,
        )
        self._watcher = asyncio.create_task(self._wait_then_enqueue(timeout))

    def _disarm(self) -> None:
        """Cancel any in-flight silence timeout watcher."""
        if self._watcher is None:
            return
        structlogger.debug(
            "silence_handler.disarm",
        )
        self._watcher.cancel()
        self._watcher = None

    async def _wait_then_enqueue(self, timeout: float) -> None:
        """Sleep for the timeout and emit a silence raw event."""
        await asyncio.sleep(timeout)
        structlogger.debug(
            "silence_handler.timeout_triggered",
            timeout=timeout,
        )
        with voice_tracing.handle_silence_span() as silence_span:
            await self._interaction_event_queue.put(
                SilenceTimeoutInteractionEvent(
                    timeout=timeout,
                    turn_triggered_at_monotonic=time.monotonic(),
                )
            )
            silence_span.record_accepted(timeout_s=timeout)
            for hook in self._on_silence_detected:
                structlogger.debug(
                    "silence_handler.silence_detected_hook_called",
                    hook=hook,
                )
                hook()
